parameters.functionCode:
const content = items[0].json.content?.[0]?.text || '{}';
let data;
try {
  data = JSON.parse(content);
} catch (e) {
  data = { headline: 'Chyba', subheadline: content, sections: [], cta: 'Kontaktujte nás' };
}

return [{
  json: {
    html: `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>${data.headline}</title>
</head>
<body>
<h1>${data.headline}</h1>
<p>${data.subheadline}</p>
${(data.sections || []).map(s => `<section><p>${s}</p></section>`).join('')}
<button>${data.cta}</button>
</body>
</html>`
  }
}];
